import numpy as np
from causallearn.graph.GeneralGraph import GeneralGraph
from causallearn.graph.GraphNode import GraphNode

# =====================================================================
# EDITABLE: implement run_causal_discovery below
# =====================================================================
def run_causal_discovery(X: np.ndarray) -> GeneralGraph:
    """
    Decision-tree classifier as a conditional-independence proxy.

    For a candidate CI statement X _||_ Y | S we train a decision tree on
    one half of the data to predict Y from S and from S+{X}; the held-out
    log-loss improvement on the other half is our dependence score.  If the
    predictive power collapses (improvement below a BIC-like threshold) we
    treat the pair as conditionally independent.  The test is symmetrized
    over prediction directions and over the two train/validation folds so
    the tree never scores itself on its own training data (no data reuse).
    Skeleton search follows PC-stable; orientation uses v-structures from
    separating sets plus Meek rules R1-R3.
    """
    from itertools import combinations
    from causallearn.graph.Edge import Edge
    from causallearn.graph.Endpoint import Endpoint
    from sklearn.tree import DecisionTreeClassifier

    rng = np.random.RandomState(0)
    n, N = X.shape
    X = X.astype(int)
    K = [int(X[:, j].max()) + 1 for j in range(N)]

    # --- 4-fold train/validation splits (never score on training data) ---
    perm = rng.permutation(n)
    qs = [perm[(i * n) // 4:((i + 1) * n) // 4] for i in range(4)]
    folds = [(np.concatenate([qs[j] for j in range(4) if j != i]), qs[i])
             for i in range(4)]
    msl = max(4, int(0.2 * np.sqrt(n * 3 // 4)))  # min samples per leaf

    base_cache = {}

    def nll_marginal(tr, va, y):
        cnt = np.bincount(X[tr, y], minlength=K[y]).astype(float)
        p = (cnt + 0.5) / (cnt.sum() + 0.5 * K[y])
        return -np.mean(np.log(p[X[va, y]]))

    def nll_tree(tr, va, y, feats):
        clf = DecisionTreeClassifier(
            criterion="entropy", min_samples_leaf=msl, random_state=0
        )
        clf.fit(X[np.ix_(tr, feats)], X[tr, y])
        P = np.full((len(va), K[y]), 1e-12)
        P[:, clf.classes_.astype(int)] = clf.predict_proba(
            X[np.ix_(va, feats)]
        )
        P = 0.99 * P + 0.01 / K[y]  # smoothing for numerical stability
        return -np.mean(np.log(P[np.arange(len(va)), X[va, y]]))

    def baseline(y, S, fi):
        key = (y, S, fi)
        if key not in base_cache:
            tr, va = folds[fi]
            if len(S) == 0:
                base_cache[key] = nll_marginal(tr, va, y)
            else:
                base_cache[key] = nll_tree(tr, va, y, list(S))
        return base_cache[key]

    def dep_score(x, y, S):
        # max over prediction directions of mean held-out NLL improvement
        best = -np.inf
        for tgt, oth in ((y, x), (x, y)):
            d = 0.0
            for fi, (tr, va) in enumerate(folds):
                d += baseline(tgt, S, fi) - nll_tree(tr, va, tgt, list(S) + [oth])
            best = max(best, d / len(folds))
        return best

    def tau(x, y):
        df = max(1, (K[x] - 1) * (K[y] - 1))
        return (0.2 + 0.15 * np.sqrt(df)) * np.log(n) / n

    # --- PC-stable skeleton with the tree-based CI proxy ---
    adj = [set(range(N)) - {i} for i in range(N)]
    seps = {}
    for depth in range(0, 5):
        snap = [frozenset(a) for a in adj]
        any_pair = False
        for x in range(N):
            for y in range(x + 1, N):
                if y not in adj[x]:
                    continue
                nx = snap[x] - {y}
                ny = snap[y] - {x}
                if len(nx) < depth and len(ny) < depth:
                    continue
                any_pair = True
                cands, seen = [], set()
                for base_set in (nx, ny):
                    if len(base_set) >= depth:
                        for S in combinations(sorted(base_set), depth):
                            if S not in seen:
                                seen.add(S)
                                cands.append(S)
                            if len(cands) >= 40:
                                break
                    if len(cands) >= 40:
                        break
                t = tau(x, y)
                for S in cands:
                    if dep_score(x, y, S) <= t:
                        adj[x].discard(y)
                        adj[y].discard(x)
                        seps[(x, y)] = set(S)
                        break
        if not any_pair:
            break

    # --- orientation: v-structures from separating sets ---
    M = np.zeros((N, N), dtype=int)
    for i in range(N):
        for j in adj[i]:
            M[i, j] = 1
    for z in range(N):
        for x, y in combinations(sorted(adj[z]), 2):
            if y in adj[x]:
                continue
            S0 = seps.get((min(x, y), max(x, y)), set())
            if z in S0:
                continue
            s0 = tuple(sorted(S0))
            s1 = tuple(sorted(set(S0) | {z}))
            d0 = dep_score(x, y, s0)
            d1 = dep_score(x, y, s1)
            if d1 > d0 and d1 > 0:
                if M[x, z] == 1:
                    M[z, x] = 0
                if M[y, z] == 1:
                    M[z, y] = 0

    # --- Meek rules R1-R3 ---
    def und(i, j):
        return M[i, j] == 1 and M[j, i] == 1

    def dird(i, j):
        return M[i, j] == 1 and M[j, i] == 0

    changed = True
    while changed:
        changed = False
        for a in range(N):
            for b in range(N):
                if not und(a, b):
                    continue
                # R1: c -> a, c and b non-adjacent  =>  a -> b
                for c in range(N):
                    if c != b and dird(c, a) and M[c, b] == 0 and M[b, c] == 0:
                        M[b, a] = 0
                        changed = True
                        break
                if not und(a, b):
                    continue
                # R2: a -> c -> b  =>  a -> b
                for c in range(N):
                    if dird(a, c) and dird(c, b):
                        M[b, a] = 0
                        changed = True
                        break
                if not und(a, b):
                    continue
                # R3: a-c, a-d, c -> b, d -> b, c,d non-adjacent  =>  a -> b
                done = False
                for c in range(N):
                    if not (und(a, c) and dird(c, b)):
                        continue
                    for d in range(c + 1, N):
                        if (und(a, d) and dird(d, b)
                                and M[c, d] == 0 and M[d, c] == 0):
                            M[b, a] = 0
                            changed = True
                            done = True
                            break
                    if done:
                        break

    # --- build CPDAG ---
    nodes = [GraphNode(f"X{i + 1}") for i in range(N)]
    G = GeneralGraph(nodes)
    for i in range(N):
        for j in range(i + 1, N):
            if M[i, j] == 1 and M[j, i] == 1:
                G.add_edge(Edge(nodes[i], nodes[j], Endpoint.TAIL, Endpoint.TAIL))
            elif M[i, j] == 1:
                G.add_directed_edge(nodes[i], nodes[j])
            elif M[j, i] == 1:
                G.add_directed_edge(nodes[j], nodes[i])
    return G
# =====================================================================
